/// <summary>
/// Contract class for order total recalculation operation.
/// </summary>
[DataContract]
internal final class SOrderRecalculateContract
{
    SOrderID orderId;

}

Method.Source:
/// <summary>
/// Gets or sets the order ID parameter.
/// </summary>
/// <param name="_orderId">The order ID to set, or default to return the current value.</param>
/// <returns>The order ID.</returns>
[DataMember]
public SOrderID parmOrderId(SOrderID _orderId = orderId)
{
    orderId = _orderId;
    return orderId;
}
